<div class="row g-4 car-insurance-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Vehicle Value ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="ci-value" class="form-control form-control-lg" value="30000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Driver Age</label><div class="input-group"><input type="number" id="ci-age" class="form-control form-control-lg" value="35" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Deductible ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="ci-ded" class="form-control form-control-lg" value="500" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Coverage Level (1-3)</label><div class="input-group"><input type="number" id="ci-cov" class="form-control form-control-lg" value="2" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Annual Miles</label><div class="input-group"><input type="number" id="ci-miles" class="form-control form-control-lg" value="12000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Accidents (Past 3yr)</label><div class="input-group"><input type="number" id="ci-acc" class="form-control form-control-lg" value="0" min="0"></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:25;--tool-color:#f97316;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Car Insurance Calculator</span><div class="output-hero-value" id="car-val">—</div><span class="output-hero-unit" id="car-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#f97316;background:rgba(0,0,0,.02);"><span class="stat-card-label">ANNUAL PREMIUM</span><span class="stat-card-value" style="color:#f97316" id="ci-annual">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">MONTHLY</span><span class="stat-card-value" style="color:#3b82f6" id="ci-monthly">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">COMPREHENSIVE</span><span class="stat-card-value" style="color:#22c55e" id="ci-comp">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#a855f7;background:rgba(0,0,0,.02);"><span class="stat-card-label">COLLISION</span><span class="stat-card-value" style="color:#a855f7" id="ci-coll">—</span></div></div></div><div class="mt-4" id="car-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="car-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="car-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="car-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const val=parseFloat($("ci-value").value)||0,age=parseFloat($("ci-age").value)||25,ded=parseFloat($("ci-ded").value)||500,cov=parseFloat($("ci-cov").value)||2,miles=parseFloat($("ci-miles").value)||12000,acc=parseFloat($("ci-acc").value)||0;const baseRate=val*0.04;const ageFactor=age<25?1.5:age>65?1.2:1.0;const dedFactor=ded>=1000?0.8:ded>=500?1.0:1.2;const covFactor=cov>=3?1.4:cov>=2?1.0:0.7;const mileFactor=miles>15000?1.15:1.0;const accFactor=1+acc*0.25;const annual=baseRate*ageFactor*dedFactor*covFactor*mileFactor*accFactor;const monthly=annual/12;const comp=annual*0.35;const coll=annual*0.45;$("car-val").textContent=fmt(annual)+"/yr";$("ci-annual").textContent=fmt(annual);$("ci-monthly").textContent=fmt(monthly)+"/mo";$("ci-comp").textContent=fmt(comp);$("ci-coll").textContent=fmt(coll);$("car-st").textContent=annual<1500?"LOW RISK":annual<3000?"MODERATE":"HIGH RISK";$("car-st").style.color=annual<1500?"#22c55e":annual<3000?"#f59e0b":"#ef4444";let ins=[];ins.push("Estimated premium: <strong>"+fmt(annual)+"/yr</strong> ("+fmt(monthly)+"/mo).");ins.push("Factors: Age "+ageFactor+"x, Deductible "+dedFactor+"x, Coverage "+covFactor+"x.");$("car-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['ci-value','ci-age','ci-ded','ci-cov','ci-miles','ci-acc'].forEach(id=>$(id).addEventListener("input",calc));$("car-cb").addEventListener("click",calc);$("car-cp").addEventListener("click",function(){navigator.clipboard.writeText("Car Insurance Calculator: "+$("car-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("car-rs").addEventListener("click",()=>{$("ci-value").value=30000;$("ci-age").value=35;$("ci-ded").value=500;$("ci-cov").value=2;$("ci-miles").value=12000;$("ci-acc").value=0;calc();});calc();});</script>
<style>.car-insurance-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.car-insurance-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.car-insurance-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.car-insurance-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.car-insurance-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.car-insurance-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style>